class TrieNode:
    __slots__ = ("children", "sentences")

    def __init__(self):
        self.children = {}
        self.sentences = {}      # every sentence below this node -> its count


class AutocompleteSystem:
    def __init__(self, sentences: list[str], times: list[int]):
        self.root = TrieNode()
        for s, t in zip(sentences, times):
            self._add(s, t)
        self.prefix = []
        self.node = self.root    # node for the current prefix; None = no match

    def _add(self, sentence: str, count: int) -> None:
        node = self.root
        for ch in sentence:
            node = node.children.setdefault(ch, TrieNode())
            node.sentences[sentence] = node.sentences.get(sentence, 0) + count

    def input(self, c: str) -> list[str]:
        if c == "#":                                  # end of sentence: record it, reset
            self._add("".join(self.prefix), 1)
            self.prefix = []
            self.node = self.root
            return []
        self.prefix.append(c)
        if self.node is not None:
            self.node = self.node.children.get(c)     # O(1) step from the previous prefix
        if self.node is None:
            return []
        ranked = sorted(self.node.sentences.items(), key=lambda kv: (-kv[1], kv[0]))
        return [s for s, _ in ranked[:3]]

class PrefixCounter {
    struct Node {
        array<int, 26> next{};                         // 0 = אין ילד (אינדקס 0 הוא השורש)
        int pass = 0;                                  // כמה מילים עוברות בצומת
    };
    vector<Node> pool{Node{}};                         // node pool: בלי new לכל צומת
public:
    void insert(const string& w) {
        int cur = 0;
        ++pool[0].pass;                                // קידומת ריקה = כל המילים
        for (char ch : w) {
            int c = ch - 'a';
            if (!pool[cur].next[c]) {
                pool[cur].next[c] = (int)pool.size();
                pool.emplace_back();                   // אחרי זה אסור להחזיק reference לצומת
            }
            cur = pool[cur].next[c];
            ++pool[cur].pass;
        }
    }
    int countPrefix(const string& p) const {
        int cur = 0;
        for (char ch : p) {
            cur = pool[cur].next[ch - 'a'];
            if (!cur) return 0;
        }
        return pool[cur].pass;
    }
};

