class Trie:
    def __init__(self):
        self.root = {}                          # תו -> צומת; המפתח '$' מסמן סוף מילה

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def with_prefix(self, prefix):
        node = self.root
        for ch in prefix:                       # O(P) עד צומת הקידומת
            if ch not in node:
                return []
            node = node[ch]
        out, stack = [], [(node, prefix)]
        while stack:                            # DFS איטרטיבי, בסדר לקסיקוגרפי
            node, word = stack.pop()
            if "$" in node:
                out.append(word)
            for ch in sorted((c for c in node if c != "$"), reverse=True):
                stack.append((node[ch], word + ch))
        return out

