// phrases[i] = רשימת מילים. מחזיר את האינדקסים (ממוינים) של הביטויים שמופיעים ברצף ב-sentence.
vector<int> phrasesInSentence(const vector<vector<string>>& phrases, const vector<string>& sentence) {
    struct Node { unordered_map<string, int> next; vector<int> ids; };
    vector<Node> trie(1);                              // trie שהאותיות שלו הן מילים שלמות
    for (int i = 0; i < (int)phrases.size(); ++i) {
        int cur = 0;
        for (const string& w : phrases[i]) {
            auto it = trie[cur].next.find(w);
            if (it == trie[cur].next.end()) {
                int id = (int)trie.size();
                trie[cur].next.emplace(w, id);
                trie.emplace_back();
                cur = id;
            } else cur = it->second;
        }
        trie[cur].ids.push_back(i);                    // ביטויים כפולים: כולם כאן
    }
    vector<bool> found(phrases.size(), false);
    for (size_t s = 0; s < sentence.size(); ++s) {     // מכל התחלה הולכים בעץ כל עוד יש המשך
        int cur = 0;
        for (size_t j = s; j < sentence.size(); ++j) {
            auto it = trie[cur].next.find(sentence[j]);
            if (it == trie[cur].next.end()) break;
            cur = it->second;
            for (int id : trie[cur].ids) found[id] = true;
        }
    }
    vector<int> out;
    for (int i = 0; i < (int)phrases.size(); ++i)
        if (found[i]) out.push_back(i);
    return out;
}

def longest_shared_prefix(lines):
    """אורך הקידומת המשותפת הארוכה ביותר של זוג שורות כלשהו (שתי שורות שונות במיקומן)."""
    root = {}
    best = 0
    for line in lines:
        node, depth = root, 0
        for ch in line:
            if ch not in node:
                node[ch] = {"#": 0}             # '#' = כמה שורות עברו בצומת
            node = node[ch]
            depth += 1
            if node["#"] >= 1:                  # שורה קודמת כבר עברה כאן
                best = max(best, depth)
            node["#"] += 1
    return best

