#include <memory>
struct Node { unique_ptr<Node> next[26]; bool end = false; };
class PatternDict {
    Node root;
    bool match(const Node* n, const string& p, size_t i) const {
        if (i == p.size()) return n->end;
        if (p[i] != '.') {
            const Node* c = n->next[p[i] - 'a'].get();
            return c && match(c, p, i + 1);
        }
        for (const auto& c : n->next)
            if (c && match(c.get(), p, i + 1)) return true;
        return false;
    }
public:
    void add(const string& w) {
        Node* n = &root;
        for (char ch : w) {
            auto& c = n->next[ch - 'a'];
            if (!c) c = make_unique<Node>();
            n = c.get();
        }
        n->end = true;
    }
    bool search(const string& p) const { return match(&root, p, 0); }
};
